using namespace std;

class Solution {
    int memo[1 << 14];

    int solve(int mask, const vector<int>& nums, int n) {
        if (memo[mask] != -1) return memo[mask];
        int k = __builtin_popcount(mask) / 2 + 1;
        if (k > n / 2) return 0;

        int res = 0;
        for (int i = 0; i < n; ++i) {
            if (!(mask & (1 << i))) {
                for (int j = i + 1; j < n; ++j) {
                    if (!(mask & (1 << j))) {
                        int next_mask = mask | (1 << i) | (1 << j);
                        int gain = k * std::gcd(nums[i], nums[j]);
                        res = max(res, gain + solve(next_mask, nums, n));
                    }
                }
            }
        }
        return memo[mask] = res;
    }

public:
    int maxScore(vector<int>& nums) {
        fill(memo, memo + (1 << 14), -1);
        return solve(0, nums, nums.size());
    }
};

import java.util.Arrays;

class Solution {
    private int[] memo = new int[1 << 14];

    private int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    private int solve(int mask, int[] nums, int n) {
        if (memo[mask] != -1) return memo[mask];
        int k = Integer.bitCount(mask) / 2 + 1;
        if (k > n / 2) return 0;

        int res = 0;
        for (int i = 0; i < n; ++i) {
            if ((mask & (1 << i)) == 0) {
                for (int j = i + 1; j < n; ++j) {
                    if ((mask & (1 << j)) == 0) {
                        int nextMask = mask | (1 << i) | (1 << j);
                        int gain = k * gcd(nums[i], nums[j]);
                        res = Math.max(res, gain + solve(nextMask, nums, n));
                    }
                }
            }
        }
        return memo[mask] = res;
    }

    public int maxScore(int[] nums) {
        Arrays.fill(memo, -1);
        return solve(0, nums, nums.length);
    }
}

