var maxScore = function(nums) {
    const n = nums.length;
    const memo = Array(1 << n).fill(-1);

    const gcd = (a, b) => b === 0 ? a : gcd(b, a % b);

    const popcount = (mask) => {
        let count = 0;
        while (mask > 0) {
            count += mask & 1;
            mask >>= 1;
        }
        return count;
    };

    function solve(mask) {
        if (memo[mask] !== -1) return memo[mask];
        const k = Math.floor(popcount(mask) / 2) + 1;
        if (k > n / 2) return 0;

        let res = 0;
        for (let i = 0; i < n; ++i) {
            if (!(mask & (1 << i))) {
                for (let j = i + 1; j < n; ++j) {
                    if (!(mask & (1 << j))) {
                        const nextMask = mask | (1 << i) | (1 << j);
                        const gain = k * gcd(nums[i], nums[j]);
                        res = Math.max(res, gain + solve(nextMask));
                    }
                }
            }
        }
        return memo[mask] = res;
    }

    return solve(0);
};
